namespace sv_48fb108f5c5b47b1b9e4021921d71493.Client.Models;

public sealed record Shipment(
    string TrackingNumber,
    string Status,
    string Location,
    DateTimeOffset EstimatedDelivery,
    IReadOnlyList<StatusUpdate> StatusUpdates);

public sealed record StatusUpdate(
    string Description,
    DateTimeOffset Timestamp);

using sv_48fb108f5c5b47b1b9e4021921d71493.Client.Models;

namespace sv_48fb108f5c5b47b1b9e4021921d71493.Client.Services;

public interface IShipmentService
{
    Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using sv_48fb108f5c5b47b1b9e4021921d71493.Client.Models;
using sv_48fb108f5c5b47b1b9e4021921d71493.Client.Services;

namespace sv_48fb108f5c5b47b1b9e4021921d71493.Services;

public sealed class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> Seeds = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-001"] = new Shipment(
            "TRK-001",
            "In Transit",
            "Memphis, TN",
            new DateTimeOffset(2026, 7, 11, 17, 0, 0, TimeSpan.Zero),
            new List<StatusUpdate>
            {
                new("Package picked up", new DateTimeOffset(2026, 7, 5, 9, 0, 0, TimeSpan.Zero)),
                new("Arrived at sorting facility", new DateTimeOffset(2026, 7, 6, 14, 30, 0, TimeSpan.Zero)),
                new("In transit to destination", new DateTimeOffset(2026, 7, 7, 8, 15, 0, TimeSpan.Zero)),
            }),
        ["TRK-002"] = new Shipment(
            "TRK-002",
            "Delivered",
            "Austin, TX",
            new DateTimeOffset(2026, 7, 7, 12, 0, 0, TimeSpan.Zero),
            new List<StatusUpdate>
            {
                new("Package picked up", new DateTimeOffset(2026, 7, 3, 10, 0, 0, TimeSpan.Zero)),
                new("Arrived at local facility", new DateTimeOffset(2026, 7, 5, 6, 0, 0, TimeSpan.Zero)),
                new("Out for delivery", new DateTimeOffset(2026, 7, 7, 8, 0, 0, TimeSpan.Zero)),
                new("Delivered", new DateTimeOffset(2026, 7, 7, 11, 42, 0, TimeSpan.Zero)),
            }),
        ["TRK-003"] = new Shipment(
            "TRK-003",
            "Processing",
            "Seattle, WA",
            new DateTimeOffset(2026, 7, 14, 18, 0, 0, TimeSpan.Zero),
            new List<StatusUpdate>
            {
                new("Label created", new DateTimeOffset(2026, 7, 7, 16, 0, 0, TimeSpan.Zero)),
            }),
    };

    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        // Simulate slow backend
        await Task.Delay(1500, ct);

        Seeds.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

@page "/shipments/{TrackingNumber}"
@using sv_48fb108f5c5b47b1b9e4021921d71493.Client.Models
@using sv_48fb108f5c5b47b1b9e4021921d71493.Client.Services
@rendermode InteractiveAuto
@inject IShipmentService ShipmentService
@inject ILogger<Shipments> Logger
@implements IDisposable

<PageTitle>Shipment @TrackingNumber</PageTitle>

@if (_loading)
{
    <div class="loading-placeholder">
        <p>Loading shipment <strong>@TrackingNumber</strong>…</p>
    </div>
}
else if (_error is not null)
{
    <div class="error-message">
        <p>@_error</p>
        <button @onclick="Retry">Retry</button>
    </div>
}
else if (_shipment is null)
{
    <div class="not-found">
        <p>No shipment found for tracking number <strong>@TrackingNumber</strong>.</p>
    </div>
}
else
{
    <div class="shipment-details">
        <h2>Shipment @_shipment.TrackingNumber</h2>
        <dl>
            <dt>Status</dt>
            <dd>@_shipment.Status</dd>
            <dt>Location</dt>
            <dd>@_shipment.Location</dd>
            <dt>Estimated Delivery</dt>
            <dd>@_shipment.EstimatedDelivery.ToString("f")</dd>
        </dl>

        <h3>Status Updates</h3>
        <ul class="status-updates">
            @foreach (var update in _shipment.StatusUpdates)
            {
                <li>
                    <time datetime="@update.Timestamp.ToString("o")">@update.Timestamp.ToString("g")</time>
                    &mdash; @update.Description
                </li>
            }
        </ul>
    </div>
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = default!;

    private Shipment? _shipment;
    private bool _loading;
    private string? _error;

    private CancellationTokenSource _cts = new();
    private string? _lastLoadedTrackingNumber;

    protected override async Task OnParametersSetAsync()
    {
        if (string.Equals(_lastLoadedTrackingNumber, TrackingNumber, StringComparison.OrdinalIgnoreCase))
            return;

        await LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        // Cancel any in-flight request
        await _cts.CancelAsync();
        _cts.Dispose();
        _cts = new CancellationTokenSource();

        _lastLoadedTrackingNumber = TrackingNumber;
        _shipment = null;
        _error = null;
        _loading = true;

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, _cts.Token);
        }
        catch (OperationCanceledException)
        {
            // Request was cancelled (navigation or dispose) — do nothing
            return;
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _error = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading shipment {TrackingNumber}", TrackingNumber);
            _error = "Something went wrong while loading the shipment. Please try again.";
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task Retry()
    {
        _lastLoadedTrackingNumber = null;
        await LoadShipmentAsync();
    }

    public void Dispose()
    {
        _cts.Cancel();
        _cts.Dispose();
    }
}

